/*
 * A324178  Integers k such that floor(sqrt(k)) + floor(sqrt(k/5)) divides k.
 * https://oeis.org/A324178
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the nth integer k (n ≥ 1) such that floor(sqrt(k)) +
 *            floor(sqrt(k/5)) divides k
 * Range:     u8 n <= 13, u16 n <= 54, u32 n <= 54, u64 n <= 54, u128 n <= 54,
 *            big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by incremental search and cached across calls. */

#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>
#include "../utils/floor_sqrt.h"   /* floor_sqrt(seq_t) */

/* Static cache of computed terms */
static seq_t *cache   = NULL;   /* Array of terms a(1)..a(current_cache_size) */
static size_t cache_size   = 0; /* Number of stored terms */
static size_t cache_cap    = 0; /* Allocated capacity */
static seq_t   last_k       = 0; /* Largest k already tested */

/* Ensure the cache contains at least 'need' terms (need ≥ 1). */
static void ensure_cache(idx_t need)
{
    /* Convert idx_t to size_t safely (need ≥ 1, offset 1). */
    size_t target = (size_t)(need - 1);

    if (cache_size > target) return;

    /* Grow array as needed. */
    if (cache_cap == 0) {
        cache_cap = 16;
        cache = (seq_t*)malloc(cache_cap * sizeof(seq_t));
    }
    while (cache_cap <= target) {
        cache_cap <<= 1;
        cache = (seq_t*)realloc(cache, cache_cap * sizeof(seq_t));
    }

    /* Generate terms until we reach the target. */
    while (cache_size <= target) {
        seq_t k = last_k + 1;
        for (;;) {
            seq_t sqrt_k  = floor_sqrt(k);
            seq_t sqrt_k5 = floor_sqrt(k / (seq_t)5);
            seq_t d = sqrt_k + sqrt_k5;
            if (d != 0 && (k % d == 0)) {
                cache[cache_size++] = k;
                last_k = k;
                break;
            }
            ++k;
        }
    }
}

seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;          /* undefined for n<1, return 0 */
    ensure_cache(n);
    return cache[(size_t)(n - 1)];
}
